def link(url,label,cls=''):return f'<a href="{url}"'+(f' class="{cls}"' if cls else '')+f'>{label}</a>'
def header(active):
 nav=[('/projects/','The stack'),('/articles/','Articles'),('/learn/','Learn'),('/author/','About')]
