def footer():return '''<footer><div class="container"><div class="footer-top"><p>Better knowledge. Stronger foundations.</p><div class="footer-links"><a href="/projects/">Projects</a><a href="/learn/">Learning resources</a><a href="https://github.com/Volland">GitHub ↗</a><a href="https://www.linkedin.com/in/pavlyshyn/">LinkedIn ↗</a></div></div><div class="footer-bottom"><span>© 2026 Volodymyr Pavlyshyn · Lean 4 Knowledge</span><div class="footer-links"><a href="/impressum/">Impressum</a><a href="/datenschutz/">Datenschutz</a><a href="/agb/">AGB</a></div><span>BUILT ON IDEAS. GROUNDED IN PROOF.</span></div></div></footer>'''
def page(path,title,desc,body,active='',lang='en'):
 target=OUT/path.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
 full=title+' — Lean 4 Knowledge' if path else 'Lean 4 Knowledge — Graphs, logic & certified reasoning'
 target.write_text(f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(full)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#f5f0e6"><meta property="og:title" content="{escape(full,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}/assets/bulletproof-knowledge.jpg"><link rel="canonical" href="{BASE}/{path.strip('/')+('/' if path else '')}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>''')
 PAGES.append('/'+path.strip('/')+('/' if path else ''))
def ph(kicker,title,intro):return f'<div class="container"><div class="page-header"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="intro">{intro}</p></div></div>'
def article_cards(items):
 return '<div class="article-grid">'+''.join(f'''<article class="article-card"><a href="/articles/{a['slug']}/"><div class="mini-illustration"><img src="/assets/article-{i%3}.svg" alt="" loading="lazy"></div><div class="meta">{a['eyebrow']} · 5 min read</div><h3>{a['title']}</h3></a><p>{a['summary']}</p><div>{link('/articles/'+a['slug']+'/','Read the article ↗','text-link')}</div></article>''' for i,a in enumerate(items))+'</div>'
def project_cards():return '<div class="project-grid">'+''.join(f'''<article class="project-card"><div class="project-symbol" aria-hidden="true">{p['symbol']}</div><div class="tag">{p['tag']}</div><h3>{p['name']}</h3><p>{p['desc']}</p><div class="card-links">{link(p['url'],'Explore project ↗')}{link(p['book'],'Mini-book ↗')}</div></article>''' for p in PROJECTS)+'</div>'
def stack():
 titles=[('Agent & application','PROPOSE A CLAIM'),('Higher-order reasoning','LEAN-ELPI'),('Semantic graph model','LEANRDF'),('Typed graph storage','TYPEDB / LADYBUG'),('Dependent type theory','LEAN 4 KERNEL')]
 return '''<div class="stack-wrap"><div class="stack-list" role="group" aria-label="Explore the conceptual stack">'''+''.join(f'<button class="stack-layer {"active" if i==4 else ""}" data-layer="{i}" aria-pressed="{str(i==4).lower()}" aria-controls="stack-detail"><span>{i+1:02} &nbsp; {t}</span><small>{sub}</small></button>' for i,(t,sub) in enumerate(titles))+'''</div><div class="stack-detail" id="stack-detail" aria-live="polite"><div class="number">05</div><h3>Check against the foundation.</h3><p>Lean’s dependent type theory lets propositions be types and proofs be terms. The kernel checks proof terms against their claimed types, relative to the definitions and axioms used.</p><a class="text-link" href="/articles/dependent-types/">Learn dependent types ↗</a></div></div><p class="stack-note">A conceptual map of responsibilities, not a single installed product. Database adapters are alternatives; connecting stored facts to proof obligations is application work.</p>'''
body='''<div class="container"><section class="hero"><div><div class="eyebrow">Graph engineering meets formal reasoning</div><h1>Knowledge<br>worth <em>building</em><br><em>on.</em></h1><p>From connected data to certified reasoning. Explore Lean 4, knowledge graphs, and the logic that makes AI agents accountable for their answers.</p><div class="actions"><a class="btn" href="/projects/">Explore the stack <span>↗</span></a><a class="btn outline" href="/learn/">Start learning <span>→</span></a></div><div class="hero-note">OPEN-SOURCE PROJECTS · PRACTICAL GUIDES · ONE LOGICAL FOUNDATION</div></div><div class="hero-art"><img src="/assets/knowledge-tree.svg" alt="A tree of knowledge connecting data, rules, types and proofs, rooted in logic beneath an orange sun" width="540" height="480"><div class="art-caption"><span>Fig. 01 / The tree of knowledge</span><span>From claims to evidence</span></div></div></section><div class="ticker"><span><b>λ</b> Higher-order logic</span><span><b>⊢</b> Kernel-checked proofs</span><span><b>◇</b> Typed knowledge graphs</span><span><b>✳</b> Open-source foundations</span></div><section class="section"><div class="section-head"><div><div class="eyebrow">The ecosystem</div><h2>Four projects. A shared idea.</h2></div><a class="text-link" href="/projects/">Meet the projects ↗</a></div>'''+project_cards()+'''</section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">A map of the territory</div><h2>From graphs to guarantees.</h2></div><p>Storage, semantics, search, and checking each have a job. Select a layer to see where it belongs.</p></div>'''+stack()+'''</section></div><section class="book-band"><div class="container book-layout"><a class="book-art" href="/book/" aria-label="Discover Bulletproof Knowledge"><img src="/assets/bulletproof-knowledge.jpg" alt="Bulletproof Knowledge book cover by Volodymyr Pavlyshyn" width="305" height="457" loading="lazy"></a><div class="book-copy"><div class="eyebrow">The book behind the work</div><h2>Bulletproof<br><em>Knowledge.</em></h2><p>Build hallucination-resistant neurosymbolic agents with Lean and logic programming. A practical journey from typed ontologies to memory and answers backed by checked evidence.</p><div class="actions"><a class="btn" href="/book/">Inside the book <span>→</span></a><a class="btn outline" href="'''+BOOK+'''">Get it on Leanpub <span>↗</span></a></div><div class="book-meta">BY VOLODYMYR PAVLYSHYN &nbsp; / &nbsp; ALSO ON AMAZON US</div></div></div></section><div class="container"><section class="section"><div class="section-head"><div><div class="eyebrow">Field notes</div><h2>Ideas you can put to work.</h2></div><a class="text-link" href="/articles/">All articles ↗</a></div>'''+article_cards(ARTICLES[:3])+'''</section><section class="learn-band"><div><div class="eyebrow">The learning corner</div><h2>A little theory.<br>A lot to build.</h2><p>Start with types and proofs. Add logic programming. Then bring the ideas to a real graph.</p><a class="text-link" href="/learn/">Find your learning path ↗</a></div><div><a class="learning-row" href="/learn/lean-foundations/"><div><small>01 / MINI-COURSE</small><strong>Lean 4 for graph engineers</strong></div><span>↗</span></a><a class="learning-row" href="/learn/elpi-reasoning/"><div><small>02 / MINI-COURSE</small><strong>ELPI & higher-order reasoning</strong></div><span>↗</span></a><a class="learning-row" href="/learn/#library"><div><small>03 / THE LIBRARY</small><strong>Free books, guides & references</strong></div><span>↗</span></a></div></section><section class="author-strip"><div class="author-small"><img src="/assets/author.jpg" alt="Volodymyr Pavlyshyn" width="62" height="62" loading="lazy"><div><h3>Built by Volodymyr Pavlyshyn.</h3><p>Software architect, author, and builder of knowledge systems.</p></div></div><a class="text-link" href="/author/">About the author ↗</a></section></div>'''
page('','Home','Lean 4 for graph engineering, typed ontologies, and certified reasoning. Explore projects, articles, mini-books, and courses by Volodymyr Pavlyshyn.',body)
# Project map and detailed architecture
body=ph('The ecosystem','A stack for knowledge.<br><em class="accent">With proof at its core.</em>','Four complementary projects connect graph engineering to Lean. Understand what each layer guarantees, and where your application must supply the bridge.')+'<div class="container page-content">'+stack()+'''<section class="section"><div class="section-head"><div><div class="eyebrow">The working proof pipeline</div><h2>Elpi finds. Lean checks.</h2></div></div><p>LeanRDF and lean-elpi form a concrete search-and-check pipeline. A search engine produces a derivation certificate; a verified checker relates accepted certificates to the formal semantics.</p><div class="diagram-full"><img src="/assets/proof-pipeline.svg" alt="Data and a claim flow through search, then a certificate crosses the trust boundary to a verified Lean checker" width="1050" height="295"></div><a class="download" href="/assets/proof-pipeline.svg" download>Download the diagram (SVG) ↓</a><div class="callout">A typed database API prevents particular mistakes in programs. A proof of entailment establishes a logical consequence. These are different contracts; neither alone establishes that an observation is true in the world.</div></section>'''
DETAILS=[
 ('Logic programming that understands binders.','LeanElpi is a Lean implementation of the ELPI dialect of λProlog. Use higher-order terms, scoped variables, hypothetical assumptions, and backtracking to express a search. The engine is usable from Lean and through language bindings.','Its optional LF certification layer records derivations and exports evidence for Lean to check. Ordinary interpreter answers are not automatically certified.','https://volland.github.io/lean-elpi/book/getting-started/'),
 ('A semantic web stack with formal contracts.','LeanRDF starts with RDF terms, graphs, parsing, and interpretations. RDFS entailment connects rules to their model-theoretic meaning. Above that sit a formalized SPARQL evaluator, OWL 2 RL and EL rules, and a SHACL Core validator.','Entailment, query evaluation, and shape validation ask different questions. Profile support does not imply arbitrary OWL reasoning. The published project documents the scope and trust assumptions of each layer.','/articles/semantic-stack/'),
 ('Relations with roles. Types across the boundary.','typedb-lean connects TypeDB to Lean through typed schemas, queries, results, and transaction modes. Lean structures describe entities and relations; migrations and schema verification help keep the application and live database aligned.','A typed transaction constrains permitted operations. It does not prove an arbitrary business invariant or the correctness of the database server. Add and discharge those obligations explicitly.','https://volland.github.io/typedb-lean/guide.html'),
 ('A property graph close to your application.','ladybug-lean provides typed node and relationship tables, checked Cypher, and a common interface for LadybugDB and a pure in-memory backend. It is a practical path for embedded graphs, local experiments, and repeatable tests.','Schema-aware query construction is not a formal proof of every database result. Differential testing of backends provides useful evidence, with a different role from a theorem.','https://volland.github.io/ladybug-lean/guide.html')]
for p,(title,desc,limit,guide) in zip(PROJECTS,DETAILS):
 body+=f'''<section class="project-feature" id="{p['id']}"><div><div class="label">{p['tag']}</div><div class="project-symbol">{p['symbol']}</div><h2>{p['name']}</h2><div class="actions">{link(p['url'],'Project website ↗','btn outline')}</div></div><div><h3>{title}</h3><p>{desc}</p><div class="callout"><strong>The boundary.</strong> {limit}</div><div class="card-links">{link(guide,'Read the guide ↗')}{link(p['book'],'Free mini-book ↗')}{link('https://github.com/Volland/'+p['id'],'Source on GitHub ↗')}</div></div></section>'''
body+='''<section class="section" id="storage"><div class="eyebrow">Choosing a foundation</div><h2>Use the graph your problem needs.</h2><div class="table-scroll"><table class="comparison"><thead><tr><th>Foundation</th><th>Natural fit</th><th>Lean connection</th><th>Proof boundary</th></tr></thead><tbody><tr><td>TypeDB</td><td>Rich domain models, role-based relations, shared database</td><td>Typed schemas, transactions, and result decoding</td><td>Application invariants need explicit proofs</td></tr><tr><td>LadybugDB</td><td>Embedded property graphs, local agent memory, Cypher</td><td>Typed graph schema and queries; pure test backend</td><td>Typed queries do not certify the native engine</td></tr><tr><td>RDF / LeanRDF</td><td>Shared vocabularies, interoperable data, semantic entailment</td><td>Formal interpretations, derivations, and checkers</td><td>Guarantees are scoped to the formalized semantics</td></tr></tbody></table></div><a class="text-link" href="/articles/graph-foundations/">Read the architecture guide ↗</a></section></div>'''
page('projects','The project stack','Map lean-elpi, LeanRDF, typedb-lean, and ladybug-lean across storage, semantics, search, and proof checking.',body,'/projects/')
