body=ph('The learning corner','Build your understanding.<br><em class="accent">One layer at a time.</em>','A practical route through Lean 4, ELPI, and graph semantics. Free mini-books, short courses, and primary references, gathered in one place.')+'''<div class="container page-content"><div class="path-steps"><div class="path-step"><h3>Learn the language.</h3><p>Types, structures, propositions, and small proofs. Start with our Lean course, then open the official books.</p></div><div class="path-step"><h3>Learn to reason.</h3><p>Use λProlog to describe a search. Learn what binders and hypothetical assumptions make possible.</p></div><div class="path-step"><h3>Bring a graph.</h3><p>Choose a data model. Read its mini-book, run the project examples, and identify the claim you want to certify.</p></div></div><section id="library" class="section" style="padding-bottom:0"><div class="section-head"><h2>The resource library.</h2><span class="result-count" aria-live="polite">14 resources</span></div><div class="filter-bar" role="group" aria-label="Filter resources">'''+''.join(f'<button class="filter-btn {"active" if v=="all" else ""}" data-filter="{v}" aria-pressed="{str(v=="all").lower()}">{n}</button>' for v,n in [('all','All'),('course','Mini-courses'),('book','Books'),('lean','Lean 4'),('elpi','ELPI'),('graph','Graphs')])+'''<label class="sr-only" for="search">Search resources</label><input id="search" class="resource-search" type="search" placeholder="Search the library…"></div><div class="resource-grid">'''
for cats,meta,title,desc,url in RESOURCES:body+=f'<article class="resource-card" data-category="{cats}"><div class="meta">{meta}</div><h3>{title}</h3><p>{desc}</p>{link(url,"Start reading ↗")}</article>'
body+='</div><p class="empty-state" hidden>No matching resources. Try another search or select All.</p></section></div>'
